mapper.select:
SELECT segment_key, next_value, segment_size
FROM ifj_id_segment
WHERE segment_key = #{segmentKey}

SELECT segment_key, next_value, segment_size
FROM ifj_id_segment
WHERE segment_key = #{segmentKey}

mapper.update:
UPDATE ifj_id_segment
SET next_value = #{nextValue}, segment_size = #{segmentSize},
    update_time = CURRENT_TIMESTAMP(3)
WHERE segment_key = #{segmentKey}
  AND next_value = #{expectedNextValue}

UPDATE ifj_id_segment
SET next_value = #{nextValue}, segment_size = #{segmentSize},
    update_time = strftime('%Y-%m-%d %H:%M:%f','now')
WHERE segment_key = #{segmentKey}
  AND next_value = #{expectedNextValue}

UPDATE ifj_id_segment
SET next_value = #{nextValue}, segment_size = #{segmentSize},
    update_time = CAST(SYS_EXTRACT_UTC(SYSTIMESTAMP) AS TIMESTAMP(3))
WHERE segment_key = #{segmentKey}
  AND next_value = #{expectedNextValue}

UPDATE ifj_id_segment
SET next_value = #{nextValue}, segment_size = #{segmentSize},
    update_time = SYSUTCDATETIME()
WHERE segment_key = #{segmentKey}
  AND next_value = #{expectedNextValue}
